WITH with_last AS (SELECT s.id, s.opened_date, s.status, top1.transaction_txn_type FROM accounts s LEFT JOIN LATERAL (SELECT c.txn_type AS transaction_txn_type FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, transaction_txn_type, CASE WHEN transaction_txn_type RLIKE '^(DEBIT|FEE)$' THEN 'CORE' ELSE 'GROUP_B' END AS transaction_txn_type_zone FROM with_last ORDER BY id NULLS FIRST;
